package project.init.framework.error;import jakarta.servlet.http.HttpServletRequest;import lombok.extern.slf4j.Slf4j;import org.springframework.context.support.DefaultMessageSourceResolvable;import org.springframework.http.HttpHeaders;import org.springframework.http.HttpStatus;import org.springframework.http.HttpStatusCode;import org.springframework.http.ResponseEntity;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.validation.FieldError;import org.springframework.web.HttpRequestMethodNotSupportedException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ControllerAdvice;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.context.request.ServletWebRequest;import org.springframework.web.context.request.WebRequest;import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;import java.util.Map;import java.util.stream.Collectors;// Dùng @ControllerAdvice để xử lý lỗi toàn hệ thống// Kế thừa ResponseEntityExceptionHandler để override các lỗi mặc định của Spring@Slf4j@ControllerAdvicepublic class GlobalExceptionHandler extends ResponseEntityExceptionHandler {    // Lỗi chung chưa xác định    @ExceptionHandler(Exception.class)    public ResponseEntity<ApiError> handleUnknownException(HttpServletRequest req) {        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(                new ApiError(                        HttpStatus.INTERNAL_SERVER_ERROR.value(),                        HttpStatus.INTERNAL_SERVER_ERROR.name(),                        req.getRequestURI()));    }    // Gọi sai method: POST vào GET...    @Override    protected ResponseEntity<Object> handleHttpRequestMethodNotSupported(HttpRequestMethodNotSupportedException ex,                                                                         HttpHeaders headers,                                                                         HttpStatusCode status,                                                                         WebRequest req) {        return ResponseEntity.status(HttpStatus.METHOD_NOT_ALLOWED).body(                new ApiError(                        HttpStatus.METHOD_NOT_ALLOWED.value(),                        HttpStatus.METHOD_NOT_ALLOWED.name(),                        ((ServletWebRequest) req).getRequest().getRequestURI()));    }    // Custom business exception    @ExceptionHandler(ApiException.class)    public ResponseEntity<ApiError> handleGException(ApiException ex, HttpServletRequest req) {        int statusCode = ex.getStatusCode();        HttpStatus status;        try {            status = HttpStatus.valueOf(statusCode);        } catch (IllegalArgumentException e) {            status = HttpStatus.CONFLICT;        }        return ResponseEntity.status(status).body(                new ApiError(                        ex.getValue(),                        ex.getMessage(),                        req.getRequestURI()));    }    // Tham số sai kiểu (string vào int...)    @ExceptionHandler(MethodArgumentTypeMismatchException.class)    public ResponseEntity<ApiError> handleTypeMismatch(MethodArgumentTypeMismatchException ex,                                                       HttpServletRequest req) {        return ResponseEntity.badRequest().body(                new ApiError(                        HttpStatus.BAD_REQUEST.value(),                        ex.getMessage(),                        req.getRequestURI()                )        );    }    // Deserialize JSON sai (ví dụ gửi chuỗi sai cấu trúc)    @Override    protected ResponseEntity<Object> handleHttpMessageNotReadable(HttpMessageNotReadableException ex,                                                                  HttpHeaders headers,                                                                  HttpStatusCode status,                                                                  WebRequest req) {        return ResponseEntity.badRequest().body(                new ApiError(                        HttpStatus.BAD_REQUEST.value(),                        ex.getMessage(),                        ((ServletWebRequest) req).getRequest().getRequestURI()                )        );    }    // Validate DTO body (@Valid) fail    @Override    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,                                                                  HttpHeaders headers, HttpStatusCode status,                                                                  WebRequest request) {        Map<String, String> errors = ex.getBindingResult().getFieldErrors().stream()                .collect(Collectors.toMap(                        FieldError::getField,                        DefaultMessageSourceResolvable::getDefaultMessage,                        (e1, e2) -> e1));        return ResponseEntity.unprocessableEntity().body(                new ApiError(                        HttpStatus.UNPROCESSABLE_ENTITY.value(),                        errors,                        ((ServletWebRequest) request).getRequest().getRequestURI()                )        );    }}